class Solution {
public:
vector t;
long long solve(vector& nums, int k, int i) {
if (i > nums.size()) return -1e18;
if (k < 0) return -1e18;
if (k == 0 && i == nums.size()) return 0;
if (t[i][k] != -1) return t[i][k];
long long take_max = -1e18;
long long skip = -1e18;
long long sum = 0;
for (int s = i; s < nums.size(); s++) {
sum += nums[s];
long long take = pow(-1, k-1) * k * sum + solve(nums, k - 1, s + 1);
take_max = max(take_max, take);
}
skip = solve(nums, k, i + 1);
return t[i][k] = max(take_max, skip);
}

