bool recur(ListNode* head, TreeNode* root, ListNode* curr) {
if(curr==NULL){
return true;
}
if(root==NULL){
return false;
}
bool left;
bool right;
if(curr->val==root->val){
left = recur(head,root->left,curr->next);
right = recur(head,root->right,curr->next);
}else{
left = recur(head,root->left,head);
right = recur(head,root->right,head);
}
return left||right;
}
bool isSubPath(ListNode* head, TreeNode* root) {
return recur(head, root, head);
}

