class Solution:
def rotate(self, nums: List[int], k: int) -> None:
l=[]
for i in range(len(nums)-1,k,-1):
l.insert(0,nums[i])
for j in range (k+1,-1,-1):
if nums[j] not in l:
l.insert(k,nums[j])

static int [][][]dp;
static int helper(int []price,int buy,int count,int index){
if(index==price.length||count==0){
return 0;
}
if(dp[index][buy][count]!=-1){
return dp[index][buy][count];
}
int ans=0;
if(buy==1){
int ans1=helper(price,0,count-1,index+1)+price[index];
int ans2=helper(price,buy,count,index+1);
ans=Math.max(ans1,ans2);
}else{
int ans1=helper(price,1,count,index+1)-price[index];
int ans2=helper(price,buy,count,index+1);
ans=Math.max(ans1,ans2);
}
return dp[index][buy][count]=ans;
}
